# R golden fixtures for gaply_core's one-sample and paired-samples t-tests
# as analyses (Research OS, Phase 8D-1; capabilities stats.analyze.one_sample_t
# and stats.analyze.paired_t).
#
# Run by its full path, from anywhere:
#
#   /usr/local/bin/Rscript make_onesample_fixtures.R
#
# R is the reference, run outside Gaply (ADR-008): nothing of R or of
# effectsize is copied into Gaply. Needs the CRAN package effectsize
# (approved for reference fixtures only, decision 67).
#
# Writes, next to this script: one synthetic data CSV per dataset
# (data_*.csv, a two-line '#' header, then `id,x` for the one-sample test or
# `id,a,b` for the paired test), golden.csv with R's answer for every case,
# and cells_bits.csv with the IEEE 754 bits of every number R read (the four
# datasets of 10,001 and 10,002 rows aside, to keep the file small). Every data
# file is written, READ BACK with read.csv(na.strings = ""), and everything is
# computed on what was read.
#
# How a case maps onto Gaply's spec (decision 255):
#   * one-sample: the column x, the test value `test_value`; the mean
#     difference is mean(x) - test_value;
#   * paired: the first column a and the second b; the difference is a - b;
#   * missing_codes are values treated as missing: in x, or in a or b.
#
# A row is left out for one reason, the first that applies, in this order:
# one-sample missing_value (x empty), missing_code (x a listed code); paired
# missing_first (a empty), missing_second (b empty), missing_code (a or b a
# listed code). Gaply counts the same way.
#
# R calls (R and effectsize versions are written into golden.csv's header):
#   t.test(x, mu = m, conf.level = 0.95)
#     -> statistic, parameter (df), p.value, stderr, estimate (mean(x));
#        conf.int minus m, the interval of the mean difference
#   t.test(a, b, paired = TRUE, conf.level = 0.95), in the (x, y) form, never
#   a formula (R 4.4 and later refuse paired = TRUE with a formula)
#     -> statistic, parameter, p.value, stderr, estimate (mean(a - b)),
#        conf.int
#   effectsize::cohens_d(x, mu = m, ci = NULL) and
#   effectsize::cohens_d(a, b, paired = TRUE, ci = NULL), which effectsize's
#   own page (cohens_d.Rd, 1.0.3) says is "equivalent to the one-sample effect
#   size on x - y" (d_z). Each is also computed directly, (mean(x) - m) / sd(x)
#   and mean(a - b) / sd(a - b), and the script stops unless the two agree
#   within 1e-14 relative.
#
# A case Gaply refuses and R computes, errors on or answers NaN for is written
# as statistic `expected_refusal` with Gaply's code as the value, and
# `r_outcome` saying what R did: computes, the start of R's error, or NaN.
#
# Synthetic data only. No manuscript or data of anyone's is read.

suppressPackageStartupMessages(library(effectsize))

args <- commandArgs(trailingOnly = FALSE)
script <- sub("^--file=", "", args[grep("^--file=", args)])
here <- dirname(normalizePath(script))

f17 <- function(x) ifelse(is.na(x), "NA", sprintf("%.17g", as.numeric(x)))

rows <- list()
cell_bits <- list()
add <- function(case, data, method, m, codes, statistic, value) {
  rows[[length(rows) + 1]] <<- data.frame(
    case = case, data = data, method = method, test_value = m,
    missing_codes = paste(codes, collapse = ";"),
    statistic = statistic, value = value, stringsAsFactors = FALSE)
}

# Write `df`, read it back, return what was read. The provenance header is
# prepended AFTER the read, so the lines R analysed are exactly the lines
# below the '#' header that the Rust test parses.
roundtrip <- function(df, name, bits = TRUE) {
  path <- file.path(here, name)
  write.csv(df, path, row.names = FALSE, quote = FALSE, na = "", fileEncoding = "UTF-8")
  classes <- c(id = "integer", setNames(rep("numeric", ncol(df) - 1), names(df)[-1]))
  back <- read.csv(path, na.strings = "", stringsAsFactors = FALSE, encoding = "UTF-8",
                   colClasses = classes)
  for (col in if (bits) names(df)[-1] else character(0)) {
    v <- back[[col]]
    for (i in which(!is.na(v))) {
      b <- paste(as.character(writeBin(as.numeric(v[i]), raw(), size = 8, endian = "big")), collapse = "")
      cell_bits[[length(cell_bits) + 1]] <<- data.frame(data = name, column = col, row = i, bits = b,
                                                        stringsAsFactors = FALSE)
    }
  }
  body <- readLines(path, encoding = "UTF-8")
  writeLines(c(
    "# Synthetic data for gaply_core's one-sample and paired t-test R golden fixtures (Research OS, Phase 8D-1).",
    "# Generated by /usr/local/bin/Rscript make_onesample_fixtures.R (do not edit by hand).",
    body), path, useBytes = TRUE)
  back
}

# What R did with a case Gaply refuses.
outcome_of <- function(expr) {
  tryCatch({
    tt <- expr
    if (is.nan(unname(tt$statistic))) "NaN" else "computes"
  }, error = function(e) paste0("error: ", gsub("[,\n]", " ", conditionMessage(e))))
}

agree <- function(case, a, b) {
  if (!(abs(a - b) <= 1e-14 * max(abs(a), abs(b), .Machine$double.xmin))) {
    stop(sprintf("%s: effectsize %.17g and the direct d %.17g differ", case, a, b))
  }
}

one_case <- function(case, name, d, m, codes = numeric(0), refusal = NULL) {
  reason <- ifelse(is.na(d$x), "missing_value",
            ifelse(d$x %in% codes, "missing_code", "used"))
  x <- d$x[reason == "used"]
  for (r in c("missing_value", "missing_code")) {
    add(case, name, "one_sample", f17(m), codes, paste0("excluded_", r), as.character(sum(reason == r)))
  }
  if (!is.null(refusal)) {
    add(case, name, "one_sample", f17(m), codes, "expected_refusal", refusal)
    add(case, name, "one_sample", f17(m), codes, "r_outcome", outcome_of(t.test(x, mu = m)))
    return(invisible())
  }
  tt <- t.test(x, mu = m, conf.level = 0.95)
  d_r <- cohens_d(x, mu = m, ci = NULL)$Cohens_d
  d_direct <- (mean(x) - m) / sd(x)
  agree(case, d_r, d_direct)
  stats <- list(
    n = length(x), mean = mean(x), sd = sd(x),
    t = unname(tt$statistic), df = unname(tt$parameter), p = tt$p.value,
    mean_difference = unname(tt$estimate) - m, se = tt$stderr,
    ci_lower = tt$conf.int[1] - m, ci_upper = tt$conf.int[2] - m,
    cohens_d = d_r)
  for (k in names(stats)) {
    add(case, name, "one_sample", f17(m), codes, k,
        if (k == "n") as.character(stats[[k]]) else f17(stats[[k]]))
  }
}

paired_case <- function(case, name, d, codes = numeric(0), refusal = NULL) {
  reason <- ifelse(is.na(d$a), "missing_first",
            ifelse(is.na(d$b), "missing_second",
            ifelse(d$a %in% codes | d$b %in% codes, "missing_code", "used")))
  a <- d$a[reason == "used"]
  b <- d$b[reason == "used"]
  for (r in c("missing_first", "missing_second", "missing_code")) {
    add(case, name, "paired", "", codes, paste0("excluded_", r), as.character(sum(reason == r)))
  }
  if (!is.null(refusal)) {
    add(case, name, "paired", "", codes, "expected_refusal", refusal)
    add(case, name, "paired", "", codes, "r_outcome", outcome_of(t.test(a, b, paired = TRUE)))
    return(invisible())
  }
  tt <- t.test(a, b, paired = TRUE, conf.level = 0.95)
  dz_r <- cohens_d(a, b, paired = TRUE, ci = NULL)$Cohens_d
  dz_direct <- mean(a - b) / sd(a - b)
  agree(case, dz_r, dz_direct)
  stats <- list(
    n_pairs = length(a), mean_first = mean(a), sd_first = sd(a),
    mean_second = mean(b), sd_second = sd(b), sd_differences = sd(a - b),
    t = unname(tt$statistic), df = unname(tt$parameter), p = tt$p.value,
    mean_difference = unname(tt$estimate), se = tt$stderr,
    ci_lower = tt$conf.int[1], ci_upper = tt$conf.int[2],
    cohens_dz = dz_r)
  for (k in names(stats)) {
    add(case, name, "paired", "", codes, k,
        if (k == "n_pairs") as.character(stats[[k]]) else f17(stats[[k]]))
  }
}

one <- function(x) data.frame(id = seq_along(x), x = x)
two <- function(a, b) data.frame(id = seq_along(a), a = a, b = b)

set.seed(20261026)

# ---- One-sample -------------------------------------------------------------

d <- roundtrip(one(c(4.25, 5.5)), "data_one_n2.csv")
one_case("one_n2", "data_one_n2.csv", d, 4)

d <- roundtrip(one(round(rnorm(30, 10, 4), 3)), "data_one_spread.csv")
one_case("one_spread", "data_one_spread.csv", d, 11)

d <- roundtrip(one(sample(1:5, 40, replace = TRUE)), "data_one_ties.csv")
one_case("one_ties", "data_one_ties.csv", d, 3)

# A 1e9 offset with an sd of 10 and a test value near the mean.
d <- roundtrip(one(1e9 + round(rnorm(50, 0, 10), 3)), "data_one_offset.csv")
one_case("one_offset_1e9", "data_one_offset.csv", d, 1e9 + 1)

d <- roundtrip(one(round(rt(60, 1.5), 5)), "data_one_heavy_tail.csv")
one_case("one_heavy_tail", "data_one_heavy_tail.csv", d, 0.5)

d <- roundtrip(one(round(rnorm(25, -500, 30), 2)), "data_one_negative.csv")
one_case("one_negative", "data_one_negative.csv", d, -480)

d <- roundtrip(one(round(rnorm(20, 0.3, 1), 4)), "data_one_mu_zero.csv")
one_case("one_mu_zero", "data_one_mu_zero.csv", d, 0)

d <- roundtrip(one(round(rnorm(18, 50, 5), 3)), "data_one_mu_positive.csv")
one_case("one_mu_positive", "data_one_mu_positive.csv", d, 52)

d <- roundtrip(one(round(rnorm(22, -3, 2), 3)), "data_one_mu_negative.csv")
one_case("one_mu_negative", "data_one_mu_negative.csv", d, -2.5)

# A test value equal to a mean that is exact in any order: t = 0 and p = 1.
d <- roundtrip(one(c(1, 2, 3, 6)), "data_one_mean_equal.csv")
one_case("one_mean_equal", "data_one_mean_equal.csv", d, 3)

d <- roundtrip(one(round(rnorm(5000, 100, 15), 3)), "data_one_large.csv")
one_case("one_large_5000", "data_one_large.csv", d, 100)

# df = 10,000, the largest the interval's quantile is measured at: computes.
d <- roundtrip(one(round(rnorm(10001, 0.02, 1), 3)), "data_one_df10000.csv", bits = FALSE)
one_case("one_df_10000", "data_one_df10000.csv", d, 0)

# df = 10,001: R computes; Gaply refuses the interval (decision 242.7).
d <- roundtrip(one(round(rnorm(10002, 0.02, 1), 3)), "data_one_df10001.csv", bits = FALSE)
one_case("one_df_10001", "data_one_df10001.csv", d, 0, refusal = "stats.onesample.quantile_out_of_range")

x <- round(rnorm(40, 10, 3), 3)
x[c(3, 8, 15, 22)] <- NA
d <- roundtrip(one(x), "data_one_missing.csv")
one_case("one_missing", "data_one_missing.csv", d, 10)

x <- round(rnorm(36, 30, 5), 2)
x[c(2, 9, 17, 25, 33)] <- -99
x[11] <- NA
d <- roundtrip(one(x), "data_one_coded.csv")
one_case("one_coded_99_ticked", "data_one_coded.csv", d, 30, codes = -99)

# All values equal to a constant that is not 0: R stops; Gaply refuses.
d <- roundtrip(one(rep(2.5, 8)), "data_one_constant.csv")
one_case("one_constant", "data_one_constant.csv", d, 1, refusal = "stats.onesample.values_constant")

# One value: R stops; Gaply refuses.
d <- roundtrip(one(c(3.1)), "data_one_single.csv")
one_case("one_single", "data_one_single.csv", d, 0, refusal = "stats.onesample.too_few_values")

# ---- Paired -----------------------------------------------------------------

d <- roundtrip(two(c(4.25, 5.5), c(3, 5.75)), "data_paired_n2.csv")
paired_case("paired_n2", "data_paired_n2.csv", d)

a <- round(rnorm(30, 50, 10), 2)
d <- roundtrip(two(a, round(a + rnorm(30, 2, 1), 2)), "data_paired_strong.csv")
paired_case("paired_strong", "data_paired_strong.csv", d)

d <- roundtrip(two(round(rnorm(30, 10, 3), 3), round(rnorm(30, 10.5, 3), 3)), "data_paired_weak.csv")
paired_case("paired_weak", "data_paired_weak.csv", d)

a <- round(rnorm(25, 20, 4), 2)
d <- roundtrip(two(a, round(a + 5 + rnorm(25, 0, 2), 2)), "data_paired_negative.csv")
paired_case("paired_negative_differences", "data_paired_negative.csv", d)

d <- roundtrip(two(sample(1:5, 40, replace = TRUE), sample(1:5, 40, replace = TRUE)), "data_paired_ties.csv")
paired_case("paired_ties", "data_paired_ties.csv", d)

a <- 1e9 + round(rnorm(50, 0, 10), 3)
d <- roundtrip(two(a, a + round(rnorm(50, 1, 3), 3)), "data_paired_offset.csv")
paired_case("paired_offset_1e9", "data_paired_offset.csv", d)

d <- roundtrip(two(round(rt(60, 1.5), 5), round(rt(60, 1.5) + 0.3, 5)), "data_paired_heavy_tail.csv")
paired_case("paired_heavy_tail", "data_paired_heavy_tail.csv", d)

a <- round(rnorm(5000, 100, 15), 3)
d <- roundtrip(two(a, round(a + rnorm(5000, 0.5, 5), 3)), "data_paired_large.csv")
paired_case("paired_large_5000", "data_paired_large.csv", d)

a <- round(rnorm(10001, 0, 1), 3)
d <- roundtrip(two(a, round(a + rnorm(10001, 0.02, 1), 3)), "data_paired_df10000.csv", bits = FALSE)
paired_case("paired_df_10000", "data_paired_df10000.csv", d)

a <- round(rnorm(10002, 0, 1), 3)
d <- roundtrip(two(a, round(a + rnorm(10002, 0.02, 1), 3)), "data_paired_df10001.csv", bits = FALSE)
paired_case("paired_df_10001", "data_paired_df10001.csv", d, refusal = "stats.onesample.quantile_out_of_range")

# A missing first, a missing second, and both in one row (counted as
# missing_first, the first reason).
a <- round(rnorm(40, 10, 3), 3)
b <- round(a + rnorm(40, 1, 2), 3)
a[c(3, 9, 20)] <- NA
b[c(5, 14, 20)] <- NA
d <- roundtrip(two(a, b), "data_paired_missing.csv")
paired_case("paired_missing", "data_paired_missing.csv", d)

# -99 as a code in either column, and in both on one row.
a <- round(rnorm(36, 30, 5), 2)
b <- round(a + rnorm(36, 1, 2), 2)
a[c(2, 17)] <- -99
b[c(9, 25)] <- -99
a[30] <- -99
b[30] <- -99
d <- roundtrip(two(a, b), "data_paired_coded.csv")
paired_case("paired_coded_99_ticked", "data_paired_coded.csv", d, codes = -99)

# Identical columns: every difference is 0; R answers t = NaN; Gaply refuses.
a <- round(rnorm(12, 5, 1), 3)
d <- roundtrip(two(a, a), "data_paired_identical.csv")
paired_case("paired_identical", "data_paired_identical.csv", d, refusal = "stats.onesample.differences_constant")

# A constant difference that is not 0: R stops; Gaply refuses. The values are
# on a quarter grid, so a - 2 is exact and every difference is exactly 2: on a
# 3-decimal grid a - (a - 2) misses 2 by an ulp on some rows, the differences
# are no longer equal, and Gaply computes (8D-1 report, open question 1).
a <- round(rnorm(10, 5, 1) * 4) / 4
d <- roundtrip(two(a, a - 2), "data_paired_constant.csv")
paired_case("paired_constant_difference", "data_paired_constant.csv", d, refusal = "stats.onesample.differences_constant")

# One pair: R stops; Gaply refuses.
d <- roundtrip(two(c(3.1), c(2.4)), "data_paired_single.csv")
paired_case("paired_single", "data_paired_single.csv", d, refusal = "stats.onesample.too_few_pairs")

all <- do.call(rbind, rows)
header <- c(
  "# R golden values for gaply_core's one-sample and paired t-tests (Research OS, Phase 8D-1).",
  "# Generated by /usr/local/bin/Rscript make_onesample_fixtures.R (do not edit by hand).",
  sprintf("# %s, %s; effectsize %s; set.seed(20261026).", R.version.string, R.version$arch,
          as.character(packageVersion("effectsize"))),
  "# t.test(x, mu = m) and t.test(a, b, paired = TRUE), conf.level = 0.95; effectsize::cohens_d(x, mu = m, ci = NULL) and cohens_d(a, b, paired = TRUE, ci = NULL); numbers %.17g; NA where R gives none.")
out <- file.path(here, "golden.csv")
writeLines(header, out)
write.table(all, out, sep = ",", quote = FALSE, row.names = FALSE, append = TRUE)

bits <- do.call(rbind, cell_bits)
bf <- file.path(here, "cells_bits.csv")
writeLines(c(
  "# The IEEE 754 bits of every value R read, for gaply_core's one-sample and paired t-test golden fixtures (Research OS, Phase 8D-1).",
  "# Generated by /usr/local/bin/Rscript make_onesample_fixtures.R (do not edit by hand)."), bf)
write.table(bits, bf, sep = ",", quote = FALSE, row.names = FALSE, append = TRUE)

cat(sprintf("wrote %d golden rows for %d cases and the bits of %d cells\n",
            nrow(all), length(unique(all$case)), nrow(bits)))
